    string[] equations = {"4x^3 + 2x^2 + 5x - 7", "x^5 + 3x^4 - x^3 - 2x^2 + x + 1", "6x^2 + 9x + 2", "2x^4 - x^3 + 6x^2 - x + 3"};
    int highestDegree = 0;
