    int index = equation.IndexOf("^");
    while (index != -1) {
      int currentDegree = int.Parse(equation.Substring(index + 1, 1));
      if (currentDegree > degree) {
        degree = currentDegree;
      }
      index = equation.IndexOf("^", index + 1);
    }
    return degree;
  }
}
