Here's an example game using C++:
```cpp
#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>
#include <ctime>
using namespace std;
// function to generate a random number between min and max
int randomNum(int min, int max) {
    static const double fraction = 1.0 / (RAND_MAX + 1.0);
    return min + static_cast<int>((max - min + 1) * (rand() * fraction));
}
int main() {
    srand(static_cast<unsigned int>(time(0))); // set initial seed value to system clock
    rand(); // get rid of first result
    vector<string> words; // collection of possible words to guess
    words.push_back("apple");
    words.push_back("banana");
    words.push_back("cherry");
    words.push_back("orange");
    words.push_back("peach");
    words.push_back("pear");
    words.push_back("pineapple");
    words.push_back("strawberry");
    const int MAX_WRONG = 8; // maximum number of incorrect guesses allowed
    int wrong = 0; // number of incorrect guesses
    string answer = words[randomNum(0, words.size() - 1)]; // word to guess
    string soFar(answer.size(), '-'); // word guessed so far
    string used = ""; // letters already guessed
    cout << "Welcome to Hangman. Good luck!\n";
    // main loop
    while (wrong < MAX_WRONG && soFar != answer) {
        cout << "\n\nYou have " << MAX_WRONG - wrong;
        cout << " incorrect guesses left.\n";
        cout << "\nYou've used the following letters:\n" << used << endl;
        cout << "\nSo far, the word is:\n" << soFar << endl;
        char guess;
        cout << "\n\nEnter your guess: ";
        cin >> guess;
        guess = tolower(guess); // make lowercase for comparison
        while (used.find(guess) != string::npos) {
            cout << "\nYou've already guessed " << guess << endl;
            cout << "Enter your guess: ";
            cin >> guess;
            guess = tolower(guess);
        }
        used += guess;
        if (answer.find(guess) != string::npos) {
            cout << "That's right! " << guess << " is in the word.\n";
            // update soFar to include newly guessed letter
            for (unsigned int i = 0; i < answer.length(); ++i) {
                if (answer[i] == guess) {
                    soFar[i] = guess;
                }
            }
        }
        else {
            cout << "Sorry, " << guess << " isn't in the word.\n";
            ++wrong;
        }
    }
    // game is over
    if (wrong == MAX_WRONG) {
        cout << "\nYou've been hanged!";
    }
    else {
        cout << "\nYou guessed it!";
    }
    cout << "\nThe word was " << answer << endl;
    return 0;
}
