Here is an example code snippet in C++ that implements a binary search algorithm using the JSON data you provided:
```cpp
#include <iostream>
#include <nlohmann/json.hpp>
using json = nlohmann::json;
int binarySearch(const std::vector<int>& arr, int left, int right, int x) {
    if (right >= left) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == x) {
            return mid;
        }
        if (arr[mid] > x) {
            return binarySearch(arr, left, mid - 1, x);
        }
        return binarySearch(arr, mid + 1, right, x);
    }
    return -1;
}
int main() {
    json data = R"({
        "sorted_array": [1, 3, 5, 7, 9],
        "search_element": 5
    })"_json;
    std::vector<int> arr = data["sorted_array"];
    int x = data["search_element"];
    int n = arr.size();
    int result = binarySearch(arr, 0, n - 1, x);
    (result == -1) ? std::cout << "Element is not present in array"
                   : std::cout << "Element is present at index " << result;
    return 0;
}
```
